"""Reproductions of report entry 54.12 for .github/scripts/graphify_ci.py (v1.5.2 verification).

Each test states the expected behaviour; it fails while the reported defect is present.
"""
import os
from pathlib import Path
import shutil
import sys
import tempfile
import unittest
from unittest import mock

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import graphify_ci  # noqa: E402

REPO = HERE.parent.parent
CORPUS = Path("testing/cypher/differential/corpus.go")


class GeneratedIgnore(unittest.TestCase):
    def setUp(self):
        self.root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, self.root)

    def test_handwritten_corpus_is_not_ignored(self):
        target = self.root / CORPUS
        target.parent.mkdir(parents=True)
        shutil.copyfile(REPO / CORPUS, target)
        ignored = graphify_ci.generated_ignore(self.root)
        print("V152_GRAPHIFY ignore list for the handwritten corpus.go:", [p for p in ignored if "corpus" in p])
        self.assertNotIn(CORPUS.as_posix(), ignored,
                         "a handwritten file whose comment mentions a generated input is ignored as generated")

    def test_control_stringer_file_is_ignored(self):
        target = self.root / "pkg" / "x" / "kind_string.go"
        target.parent.mkdir(parents=True)
        target.write_text("// Code generated by stringer; DO NOT EDIT.\n\npackage x\n", encoding="utf-8")
        self.assertIn("pkg/x/kind_string.go", graphify_ci.generated_ignore(self.root))


class FailedPath(unittest.TestCase):
    def test_failure_report_does_not_replace_a_newer_heads_report(self):
        calls = []
        head_b, base_c, head_a = "b" * 40, "c" * 40, "a" * 40

        class StandIn:
            def __init__(self, base, repo, token):
                self.repo = "org/repo"

            def request(self, method, path, body=None):
                calls.append((method, path, body))
                if method == "GET" and path == "/repos/org/repo/pulls/17":
                    return {"state": "open", "head": {"sha": head_b}, "base": {"sha": base_c}}
                if method == "GET" and path.startswith("/repos/org/repo/issues/17/comments"):
                    return [{"id": 123, "user": {"login": "github-actions[bot]"},
                             "body": graphify_ci.MARKER + "\nreport for head " + head_b}]
                return None

        env = {"GITHUB_API_URL": "https://example.test", "GITHUB_REPOSITORY": "org/repo",
               "GITHUB_TOKEN": "fixture", "GITHUB_SERVER_URL": "https://example.test",
               "GITHUB_RUN_ID": "100", "PR_NUMBER": "17", "PR_HEAD_SHA": head_a, "PR_BASE_SHA": base_c}
        with mock.patch.dict(os.environ, env), mock.patch.object(graphify_ci, "API", StandIn):
            graphify_ci.failed()
        writes = [(m, p) for m, p, _ in calls if m != "GET"]
        print("V152_GRAPHIFY failed() requests:", [(m, p) for m, p, _ in calls])
        self.assertEqual([], writes,
                         "the failure path for head aaaa... wrote over the report of the PR's current head bbbb...")


if __name__ == "__main__":
    unittest.main()
